// Headless simulation: run the real engine to completion with a scripted "AI" for both sides.
import { Game, terrainAt } from '/home/runner/work/PlayGround/PlayGround/js/engine.js'
import { MAX_TURNS } from '/home/runner/work/PlayGround/PlayGround/js/data.js'

function playSide(game, side) {
  const alive = game.units.filter(u => u.alive && u.side === side && !u.cannotAct)
  for (const u of alive) {
    if (!u.alive) continue
    // Try to move toward nearest enemy if not moved
    if (u.side === 'nva' && !u.moved) {
      const target = game.units.filter(t => t.alive && t.side !== 'nva')
        .sort((a, b) => game.hexDistance(a, { c: u.c, r: u.r }) - game.hexDistance(b, { c: u.c, r: u.r }))[0]
      if (target && target.c !== undefined) {
        try { game.moveUnit(u.id, target.c, target.r, { autoToNearest: true }) } catch {}
      }
    }
    // Try to fire
    const enemies = game.units.filter(t => t.alive && t.side !== u.side)
    for (const t of enemies) {
      if (!u.alive) break
      try { if (game.fireAt(u.id, t.id)) break } catch {}
    }
  }
}

let outcomeTally = { victory: 0, defeat: 0, other: 0 }
for (let run = 0; run < 5; run++) {
  const events = []
  const game = new Game({ seed: 1000 + run * 7, onEvent: e => events.push(e) })
  game.setDelay(async () => {})
  game.start()
  let guard = 0
  while (!game.result && guard++ < 200) {
    playSide(game, 'us')
    playSide(game, 'nva')
    // check rendering of current phase
    if (game.phase === 'briefing') { console.error('stuck in briefing'); break }
    if (game.phase === 'player') {
      game.endTurn()
    }
    // if engine switched to enemy phase synchronously, step it
    if (game.phase === 'enemy') {
      guard++
      if (guard > 500) { console.error('enemy phase never resolved'); break }
    }
  }
  const counts = { player: 0, enemy: 0 }
  for (const e of events) {
    if (e.type === 'gameOver') {
      outcomeTally[e.victory ? 'victory' : 'defeat']++
      console.log(`run ${run}: gameOver victory=${e.victory} result=${game.result} grade=${game.grade} score=${game.score} turns=${game.turn}/${MAX_TURNS}`)
      break
    }
  }
  if (!game.result) { console.log(`run ${run}: ended WITHOUT result — turn=${game.turn} phase=${game.phase}`); outcomeTally.other++ }
}

console.log('TALLY', outcomeTally)

