// Headless simulation: run the real engine to completion using its async turn flow.
import { Game } from '/home/runner/work/PlayGround/PlayGround/js/engine.js'
import { MAX_TURNS } from '/home/runner/work/PlayGround/PlayGround/js/data.js'

const tally = { victory: 0, defeat: 0, noresult: 0 }

for (let run = 0; run < 5; run++) {
  const events = []
  const game = new Game({ seed: 1000 + run * 7, onEvent: e => events.push(e) })
  game.setDelay(async () => {})
  game.start()
  let guard = 0
  while (!game.result && guard++ < 40) {
    // Player phase
    for (const u of game.playerCombatUnits()) {
      if (!u.alive) continue
      if (!u.moved) {
        const map = game.reachableMap(u)
        // pick nearest reachable cell to nearest enemy
        const target = game.aliveUnits('nva')[0]
        if (target) {
          let best = null, bestD = Infinity
          for (const key of Object.keys(map)) {
            const [c, r] = key.split(',').map(Number)
            if (map[key] === Infinity || map[key] == null) continue
            const d = game.hexDistance({ c, r }, target)
            if (d < bestD) { bestD = d; best = { c, r } }
          }
          if (best) await game.movePlayerUnit(u.id, best.c, best.r)
        }
      }
      const targets = game.targetsInRange(u)
      if (targets.length) await game.attack(u.id, targets[0].id)
    }
    if (game.result) break
    await game.endPlayerTurn()
  }
  const over = events.find(e => e.type === 'gameOver')
  if (game.result) {
    if (game.result.victory) tally.victory++; else tally.defeat++
    console.log(`run ${run}: result=${game.result.victory ? 'VICTORY' : 'DEFEAT'} reason="${game.result.reason}" grade=${game.grade} score=${game.score} turn=${game.turn}/${MAX_TURNS}`)
  } else {
    tally.noresult++
    console.log(`run ${run}: NO RESULT (turn=${game.turn} phase=${game.phase})`)
  }
}
console.log('TALLY', JSON.stringify(tally))

