// End-to-end browser test of Firebase Raven using system Chromium.
import puppeteer from 'puppeteer-core'
import http from 'http'
import { readFile } from 'fs/promises'
import { extname, join } from 'path'

const ROOT = '/home/runner/work/PlayGround/PlayGround'
const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.json': 'application/json' }

const server = http.createServer(async (req, res) => {
  const path = req.url === '/' ? '/index.html' : req.url.split('?')[0]
  try {
    const data = await readFile(join(ROOT, path))
    res.writeHead(200, { 'Content-Type': MIME[extname(path)] || 'application/octet-stream' })
    res.end(data)
  } catch {
    res.writeHead(404); res.end('nope')
  }
})
await new Promise(r => server.listen(8399, r))

const browser = await puppeteer.launch({
  executablePath: '/usr/bin/chromium',
  headless: 'new',
  args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage', '--window-size=1440,900']
})
const page = await browser.newPage()
await page.setViewport({ width: 1440, height: 900 })
const errors = []
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message))
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()) })

await page.goto('http://localhost:8399/', { waitUntil: 'networkidle0' })

// 1. Briefing visible
const startVisible = await page.$eval('#btn-start', b => b.offsetParent !== null || getComputedStyle(b).display !== 'none')
console.log('briefing start button visible:', Boolean(startVisible))

// 2. Start the game
await page.click('#btn-start')
await page.waitForFunction(() => window.__RAVEN__?.state()?.phase === 'player', { timeout: 5000 })
const st1 = await page.evaluate(() => window.__RAVEN__.state())
console.log('after start: phase=', st1.phase, 'turn=', st1.turn, 'units=', st1.units.length, 'cp=', st1.cp)

// 3. Unit list rendered
const listCount = await page.$$eval('#unit-list > *', els => els.length)
console.log('unit list rows:', listCount)
const stripCount = await page.$$eval('#unit-strip > *', els => els.length)
console.log('unit strip buttons:', stripCount)

// 4. Canvas is actually painted (non-blank)
const canvasInfo = await page.evaluate(() => {
  const cv = document.getElementById('board')
  const ctx = cv.getContext('2d')
  const d = ctx.getImageData(0, 0, cv.width, Math.min(cv.height, 400)).data
  let lit = 0
  for (let i = 0; i < d.length; i += 40) if (d[i + 3] > 0 || d[i] + d[i + 1] + d[i + 2] > 20) lit++
  return { w: cv.width, h: cv.height, sampled: Math.floor(d.length / 40), lit }
})
console.log('canvas:', JSON.stringify(canvasInfo))

// 5. Canvas click selects a unit (derive hex pixel from live geometry)
const clicked = await page.evaluate(() => {
  const R = window.__RAVEN__.renderer
  const game = window.__RAVEN__.game
  const unit = game.playerCombatUnits()[0]
  // find board-wrap offset to convert canvas coords to page coords
  const cv = document.getElementById('board')
  const rect = cv.getBoundingClientRect()
  const px = R?.hexPixel?.(unit.c, unit.r)
  document.querySelectorAll('.actionbar button, .support-btn').forEach(() => {})
 return { unitId: unit.id, hasHexPixel: typeof R?.hexPixel === 'function', rect: { x: rect.x, y: rect.y }, px }
})
console.log('click-probe:', JSON.stringify(clicked))

