const US_VEHICLE = {
  base: 'rgba(80,88,56,.98)', light: 'rgba(116,124,80,.92)', dark: 'rgba(54,60,38,.95)',
  track: 'rgba(26,29,21,.97)', trackLit: 'rgba(88,92,72,.9)', metal: 'rgba(36,40,28,.96)',
  metalLit: 'rgba(112,117,88,.85)'
