  seg(ctx, r * 0.2, 0, r * 1.0, 0, r * 0.1, 'rgba(36,40,28,.98)')
  seg(ctx, r * 0.64, 0, r * 0.64, 0, r * 0.13, 'rgba(48,52,36,.95)')
  dot(ctx, r * 1.06, 0, r * 0.06, 'rgba(20,22,16,.98)')
  // red star + antennas
