  ctx.fill()
  roundedRect(ctx, -r * 0.16, r * 0.37, r * 0.34, r * 0.09, r * 0.03)
  ctx.fill()
  // cupola with M2
  dot(ctx, r * 0.14, -r * 0.02, r * 0.2, 'rgba(72,78,52,.97)')
  ctx.strokeStyle = V.metalLit
  ctx.lineWidth = r * 0.035
  ctx.beginPath()
  ctx.arc(r * 0.14, -r * 0.02, r * 0.15, 0, TAU)
