export function h2(c, r, s = 0) {
  let x = Math.imul(c + 17, 374761393) ^ Math.imul(r + 31, 668265263) ^ Math.imul(s + 7, 1274126177)
  x = Math.imul(x ^ (x >>> 13), 1274126177)
  return ((x ^ (x >>> 16)) >>> 0) / 4294967296
}

